using System.Collections.Concurrent;
using System.Text.Json;
using SimplePZMapmaker.Core;
using SimplePZMapmaker.Core.Export;
namespace SimplePZMapmaker.Web.Services;

public sealed record OsmWorldImportRequest(GeoBounds Bounds,double MetresPerTile=1,int SectionSize=1024,int OriginCellX=100,int OriginCellY=100,int Seed=42,string Name="OpenStreetMap world",WorldProject? ExistingWorld=null,bool PreserveEdits=false,double RotationDegrees=0,string SourceMode="auto",string? SourceId=null,string RegionalProfile="default",GeographicWarpDefinition? Warp=null,bool PreferSections=false,bool AllowExpandedLayout=false);
public sealed record OsmWorldPlan(WorldGeoReference GeoReference,int Columns,int Rows,int SectionSize,int Cells,int Width,int Height,bool RequiresExpandedLayout=false,int Sections=0,long EstimatedBaseRasterBytes=0,bool PreferSections=false,string AssemblyMode="compatibility",int MaxResidentCells=0);
public sealed class OsmWorldImportService(OsmClient client,GameAssetCatalog assets,string directory,StaticModelCatalog? models=null,OsmImportTimeouts? timeouts=null,WorldStore? workspaceStore=null):IDisposable
{
 private readonly OsmImportTimeouts timing=timeouts??new();
 private readonly StaticModelCatalog modelCatalog=models??new(assets);
 private sealed class Job(string id){public string Id=id;public string Status="queued";public OsmProgress Progress=new("queued",0,0);public DateTimeOffset Created=DateTimeOffset.UtcNow;public string? Error;public string? File;public string? WorkspaceId;public long? WorkspaceRevision;public string? SourceId;public string? Recovery;public bool RetainedRegionalSource;public OsmWorldSectionImport.Statistics? Assembly;public List<string> Warnings=[];public CancellationTokenSource Cancel=new();public Task? Task;public object Sync=new();}
 private readonly ConcurrentDictionary<string,Job> jobs=new();private readonly object admission=new();private bool disposed;
 public static OsmWorldPlan Plan(OsmWorldImportRequest request){
  if(request is null||string.IsNullOrWhiteSpace(request.Name)||request.Name.Length>80||request.Name.Any(char.IsControl)||request.SectionSize is <256 or >2048||request.SectionSize%256!=0)throw new ArgumentException("Specify a name and section dimensions of 256-2,048 tiles, in multiples of 256.");
  if(request.SourceMode is not("auto" or "global" or "overpass" or "regional" or "file"))throw new ArgumentException("Choose automatic, Overpass, regional, or saved-file geographic data.");
  if(request.SourceId is not null&&!OsmSourceFiles.SafeId(request.SourceId)||request.SourceMode=="file"&&request.SourceId is null)throw new ArgumentException("Choose a valid saved geographic source for file import.");
  if(request.SourceMode=="regional"&&!OsmClient.CanUseExtract(request.Bounds))throw new ArgumentException("Regional extracts currently support only the Smolensk area. Use automatic, Overpass, or a saved file for other locations.");
  if(request.RegionalProfile is not("default" or "ru-rural"))throw new ArgumentException("Choose a supported regional profile.");
  var reference=new WorldGeoReference{Bounds=request.Bounds,MetresPerTile=request.MetresPerTile,OriginCellX=request.OriginCellX,OriginCellY=request.OriginCellY,RotationDegrees=request.RotationDegrees,Warp=request.Warp,RegionalProfile=request.RegionalProfile=="default"?null:request.RegionalProfile};var size=GeographicProjection.RequiredTiles(reference);var columns=Math.Max(1,(int)Math.Ceiling(size.Width/(double)request.SectionSize));var rows=Math.Max(1,(int)Math.Ceiling(size.Height/(double)request.SectionSize));var sections=(long)columns*rows;var cellCount=sections*(request.SectionSize/256)*(request.SectionSize/256);if(sections>WorldLayoutLimits.MaxSections||cellCount>WorldLayoutLimits.MaxWorldCells)throw new ArgumentException($"The area exceeds {WorldLayoutLimits.MaxSections:N0} sections or {WorldLayoutLimits.MaxWorldCells:N0} native cells. Increase the tile scale or reduce the bounds.");
  var cells=(int)cellCount;var expanded=sections>WorldLayoutLimits.NormalSections||cells>WorldLayoutLimits.NormalImportCells;
  if(expanded&&!request.AllowExpandedLayout)throw new ArgumentException($"This area needs {sections} connected sections and {cells} native cells. Explicitly allow the expanded layout to keep the selected area and scale (normal limits: 128 sections / 768 cells; maximum: {WorldLayoutLimits.MaxWorldCells:N0}). Expanded imports save sections incrementally; sources and shared object metadata have separate bounded budgets.");
  if(request.OriginCellX+(columns-1)*request.SectionSize/256>1000||request.OriginCellY+(rows-1)*request.SectionSize/256>1000)throw new ArgumentException("The import exceeds the editor's supported cell coordinates.");
  if(request.PreserveEdits&&cells>WorldLayoutLimits.InMemoryCells)throw new ArgumentException("Refreshing a supplied complete authored world is limited to 8,192 cells. Import the larger area as a new section workspace.");
  if(request.ExistingWorld is {} old&&request.PreserveEdits){WorldAssembler.Validate(old);if(old.GeoReference is not {} prior||JsonSerializer.Serialize(prior,NativeMapExporter.JsonOptions)!=JsonSerializer.Serialize(reference,NativeMapExporter.JsonOptions))throw new ArgumentException("To preserve edits, keep the geographic world's original bounds, scale, and coordinate origin.");if(old.Maps.Count!=columns*rows||old.Maps.Any(m=>m.Project.Width!=request.SectionSize||m.Project.Height!=request.SectionSize||(m.Project.WorldX-request.OriginCellX)%(request.SectionSize/256)!=0||(m.Project.WorldY-request.OriginCellY)%(request.SectionSize/256)!=0||m.Project.WorldX<request.OriginCellX||m.Project.WorldY<request.OriginCellY||m.Project.WorldX>=request.OriginCellX+columns*request.SectionSize/256||m.Project.WorldY>=request.OriginCellY+rows*request.SectionSize/256))throw new ArgumentException("The existing world layout differs. To preserve edits, keep the original section dimensions and positions.");}
  return new(reference,columns,rows,request.SectionSize,cells,columns*request.SectionSize,rows*request.SectionSize,expanded,(int)sections,WorldLayoutLimits.EstimateBaseRasterBytes(cells),request.PreferSections||expanded,(request.PreferSections||expanded)&&!request.PreserveEdits?"incremental-sections":"compatibility",(request.PreferSections||expanded)&&!request.PreserveEdits?Math.Min(cells,OsmWorldSectionImport.MaximumWindowCells):cells);
 }
 public object Start(OsmWorldImportRequest request){var plan=Plan(request);if(plan.RequiresExpandedLayout&&workspaceStore is null)throw new ArgumentException("Expanded imports require a disk section workspace store.");lock(admission){ObjectDisposedException.ThrowIf(disposed,this);if(jobs.Values.Any(j=>j.Status is "queued" or "running"))throw new ArgumentException("An OSM import is already running. Wait for it to finish or cancel it.");foreach(var old in jobs.Values.OrderByDescending(j=>j.Created).Skip(7))if(jobs.TryRemove(old.Id,out _)){old.Cancel.Dispose();if(old.WorkspaceId is null&&old.File is {} file&&File.Exists(file))File.Delete(file);}var id=Guid.NewGuid().ToString("N");var job=new Job(id){Progress=new("queued",0,plan.Columns*plan.Rows)};jobs[id]=job;var isolated=request with{ExistingWorld=request.PreserveEdits&&request.ExistingWorld is {} world?WorldAssembler.Clone(world):null};job.Task=Task.Run(()=>Run(job,isolated,plan));return new{id,plan};}}
 public object Status(string id){var job=Get(id);lock(job.Sync)return new{id=job.Id,status=job.Status,progress=job.Progress,createdAtUtc=job.Created,error=job.Error,warnings=job.Warnings.ToArray(),sourceId=job.SourceId,retainedRegionalSource=job.RetainedRegionalSource,assembly=job.Assembly,recovery=job.Recovery,workspaceId=job.WorkspaceId,workspaceRevision=job.WorkspaceRevision,resultKind=job.WorkspaceId is null?"world":"sections",ready=job.Status=="completed"};}
 public object Cancel(string id){var job=Get(id);lock(job.Sync){if(job.Status is "queued" or "running")job.Cancel.Cancel();}return Status(id);}
 public string ResultFile(string id){var job=Get(id);lock(job.Sync){if(job.Status!="completed"||job.File is null)throw new ArgumentException("The world is not ready. A partial import cannot be returned as a complete project.");return job.File;}}
 private Job Get(string id)=>WorldAssembler.SafeId(id)&&jobs.TryGetValue(id,out var job)?job:throw new ArgumentException("Import task not found.");
 private async Task Run(Job job,OsmWorldImportRequest request,OsmWorldPlan plan){try{
  timing.Validate();using var deadline=CancellationTokenSource.CreateLinkedTokenSource(job.Cancel.Token);deadline.CancelAfter(request.SourceMode is "auto" or "global"?timing.SourceMaximum:TimeSpan.FromMinutes(15));var token=deadline.Token;lock(job.Sync)job.Status="running";
  var progress=new InlineProgress<OsmProgress>(value=>{lock(job.Sync){job.Progress=value;if(value.Warning is {} warning&&!job.Warnings.Contains(warning)&&job.Warnings.Count<64)job.Warnings.Add(warning);}});var download=await client.FetchForImport(request.Bounds,request.SourceMode,request.SourceId,token,progress,64_000_000,world:true);
  lock(job.Sync){job.SourceId=download.SourceId;job.Warnings=job.Warnings.Concat(download.Warnings).Distinct().Take(64).ToList();}token.ThrowIfCancellationRequested();deadline.CancelAfter(timing.ProcessingMaximum);
  var geometry=new OsmGeometrySet(64_000_000);geometry.Add(download.Data);var attribution=geometry.IsGeoJson?"Source: imported GeoJSON. Rights to the original data are determined by its provider.":"Map data © OpenStreetMap contributors — https://www.openstreetmap.org/copyright — ODbL 1.0";
  var world=new WorldProject{Name=request.Name,Id=request.ExistingWorld?.Id??Guid.NewGuid().ToString("N"),GeoReference=plan.GeoReference,LinearFeatures=request.PreserveEdits?request.ExistingWorld?.LinearFeatures??[]:[],Buildings=request.PreserveEdits?request.ExistingWorld?.Buildings??[]:[],Elevation=request.PreserveEdits?request.ExistingWorld?.Elevation:null};
  // Preserve edits keeps authored world fences and their styles; imported world fences are rebuilt from the refreshed source below.
  if(request.PreserveEdits&&request.ExistingWorld is {} fenced){world.Fences=fenced.Fences.Where(f=>f.SourceId is null).ToList();world.FenceStyles=[..fenced.FenceStyles];world.GateStyles=[..fenced.GateStyles];world.Decorations=[..fenced.Decorations];}var total=plan.Columns*plan.Rows;var completed=0;var warnings=new HashSet<string>(download.Warnings){attribution,$"Source: {download.Source}; data date: {download.DataTimestamp??"not specified"}; retrieved: {download.RetrievedAtUtc:O}; requests: {download.Requests}; cache: {(download.FromCache?"yes":"no")}."};
  if(plan.AssemblyMode=="incremental-sections"&&workspaceStore is not null){
   var disk=await new OsmWorldSectionImport(workspaceStore,assets,modelCatalog).BuildAsync(job.Id,request,plan,geometry.Serialize(download.DataTimestamp),(x,y)=>ComposeSection(request,plan,geometry,attribution,x,y,warnings,token),new InlineProgress<OsmProgress>(v=>progress.Report(v with{Source=v.Source??download.Source,DataTimestamp=v.DataTimestamp??download.DataTimestamp})),warnings,token);
   lock(job.Sync){job.File=disk.File;job.WorkspaceId=job.Id;job.WorkspaceRevision=disk.Revision;job.Assembly=disk.Assembly;job.Warnings=warnings.Take(64).ToList();job.Progress=new("completed",total,total,download.Source,download.DataTimestamp);job.Status="completed";}return;
  }
  if(plan.Cells>WorldLayoutLimits.InMemoryCells)throw new ArgumentException("Large imports require incremental disk section assembly.");
  for(var y=0;y<plan.Rows;y++)for(var x=0;x<plan.Columns;x++){
   world.Maps.Add(ComposeSection(request,plan,geometry,attribution,x,y,warnings,token));progress.Report(new("compose",++completed,total,download.Source,download.DataTimestamp));
  }
  if(request.PreserveEdits&&request.ExistingWorld is {} priorWorld)foreach(var b in world.Buildings){foreach(var c in WorldAssembler.BuildingCells(b)){var targetMember=WorldAssembler.MemberAt(world,c.X,c.Y);var prior=WorldAssembler.MemberAt(priorWorld,c.X,c.Y);if(targetMember is null||prior is null)continue;var p=targetMember.Project;var oldp=prior.Project;p.Terrain[(c.Y-p.WorldY*256)*p.Width+c.X-p.WorldX*256]=oldp.Terrain[(c.Y-oldp.WorldY*256)*oldp.Width+c.X-oldp.WorldX*256];}if(b.SourceId is not null)foreach(var m in world.Maps){m.Project.Buildings.RemoveAll(local=>local.SourceId==b.SourceId);SiteModel.DetachMissingMembers(m.Project);}}
  if(request.PreserveEdits&&request.ExistingWorld is {} decorated&&world.Decorations.Count>0){var decorationWarnings=new List<string>();WorldAssembler.KeepSharedDecorations(world,decorated,decorationWarnings);foreach(var warning in decorationWarnings)warnings.Add(warning);}
  progress.Report(new("world-fences",total,total,download.Source,download.DataTimestamp));
  var fenceWarnings=new List<string>();GeographicImporter.PromoteSharedFences(world,fenceWarnings);foreach(var warning in fenceWarnings)warnings.Add(warning);
  progress.Report(new("world-buildings",total,total,download.Source,download.DataTimestamp));
  var worldBuildingWarnings=new List<string>();GeographicImporter.ImportWorldBuildings(geometry.Serialize(download.DataTimestamp),world,request.Seed,worldBuildingWarnings,token);foreach(var warning in worldBuildingWarnings)warnings.Add(warning);foreach(var b in world.Buildings){if(!b.Attribution.Contains(attribution))b.Attribution.Add(attribution);AssetRules.Building(b,assets);if(b.Design is {} d)foreach(var f in d.Floors)foreach(var m in f.StaticModels)modelCatalog.Validate(m);}
  progress.Report(new("world-validate",total,total,download.Source,download.DataTimestamp));
  WorldEndpoints.Validate(world,assets,modelCatalog);token.ThrowIfCancellationRequested();progress.Report(new("world-save",total,total,download.Source,download.DataTimestamp));
  var saved=await OsmWorldResultWriter.SaveAsync(directory,job.Id,world,workspaceStore,token,preferSections:plan.PreferSections);
  lock(job.Sync){job.File=saved.File;job.WorkspaceId=saved.WorkspaceId;job.WorkspaceRevision=saved.WorkspaceRevision;job.Warnings=warnings.Take(64).ToList();job.Progress=new("completed",total,total,download.Source,download.DataTimestamp);job.Status="completed";}
 }catch(OperationCanceledException){lock(job.Sync){job.Status=job.Cancel.IsCancellationRequested?"cancelled":"failed";if(job.Cancel.IsCancellationRequested)job.Error="Import canceled. The original world was preserved.";else if(job.Progress.Phase=="region-download"){job.Recovery="resume-download";job.Error=$"Regional download stopped at {job.Progress.BytesReceived??0:N0} bytes because its time budget expired. Partial bytes remain in the cache; resume the regional download. The original world was preserved.";}else if(job.SourceId is not null){job.Recovery="retry-build";job.Error="The geographic source is saved, but world assembly exceeded its time budget. Retry the build or reduce the area. No source upload is needed; the original world was preserved.";}else{job.RetainedRegionalSource=job.Progress.Phase is "pbf-index" or "region-index" or "region-downloaded";job.Recovery=job.RetainedRegionalSource?"retry-processing":null;job.Error=job.RetainedRegionalSource?"The regional PBF is complete, but local processing exceeded its time budget. The complete source is retained; retry processing. The original world was preserved.":"Preparing the geographic source exceeded its time budget. The original world was preserved.";}}}catch(Exception e) when(e is ArgumentException or HttpRequestException or IOException or UnauthorizedAccessException or JsonException or InvalidOperationException){lock(job.Sync){job.Status="failed";job.Error=e.Message;job.RetainedRegionalSource=e is RegionalProcessingException{Retained:true};job.Recovery=e is RegionalTransferTimeoutException?"resume-download":job.RetainedRegionalSource?"retry-processing":job.SourceId is not null?"retry-build":null;}}}
 private WorldMapMember ComposeSection(OsmWorldImportRequest request,OsmWorldPlan plan,OsmGeometrySet geometry,string attribution,int x,int y,HashSet<string> warnings,CancellationToken token){
   token.ThrowIfCancellationRequested();var cellX=request.OriginCellX+x*request.SectionSize/256;var cellY=request.OriginCellY+y*request.SectionSize/256;var projection=new GeographicProjection(plan.GeoReference,cellX,cellY);var bounds=projection.SectionBounds(request.SectionSize,request.SectionSize);var old=request.ExistingWorld?.Maps.SingleOrDefault(m=>m.Project.WorldX==cellX&&m.Project.WorldY==cellY);
   var project=old?.Project??MapGenerator.Generate(new(){Kind="blank",Size=request.SectionSize,Seed=request.Seed,Name=$"{request.Name[..Math.Min(60,request.Name.Length)]} {x+1}/{y+1}"});project.WorldX=cellX;project.WorldY=cellY;project.WorldSection=true;project.Version=Math.Max(project.Version,6);
   // Rotated worlds retain the complete section grid. A padding section can have no
   // positive intersection with the reference bounds; it has no geographic query bounds.
   var intersects=bounds.West<bounds.East&&bounds.South<bounds.North;var json=intersects?geometry.ForSection(bounds):null;if(json is not null&&OsmGeometrySet.HasFeatures(json)){var result=GeographicImporter.Import(json,project,bounds,token,request.PreserveEdits,projection,request.RegionalProfile);project=result.Project;foreach(var warning in result.Warnings)warnings.Add(warning);}else{if(request.PreserveEdits&&old is not null)project=RefreshEmptySection(project,token);project.Bounds=intersects?bounds:null;project.MetresPerTile=request.MetresPerTile;}
   if(!project.Attribution.Contains(attribution))project.Attribution.Add(attribution);AssetRules.Project(project,assets);modelCatalog.Validate(project);return new(){Id=old?.Id??Guid.NewGuid().ToString("N"),Project=project};
 }
 private static MapProject RefreshEmptySection(MapProject previous,CancellationToken token){
  // The core importer rejects empty input. Refresh its source layers explicitly while retaining
  // the same authored terrain protections used by a nonempty geographic refresh.
  token.ThrowIfCancellationRequested();var p=LinearFeatureEditor.Rebuild(previous,[]);var terrain=p.Terrain;var mask=TerrainEditMask.Decode(p);p.Terrain=new Terrain[p.Width*p.Height];
  // Rebuild removed all strokes; take authored paths from the original isolated input.
  var lines=previous.LinearFeatures.Where(f=>f.Modified||f.SourceId is null).Select(NeighborhoodPlanner.Copy).ToList();foreach(var line in lines){line.Underlay=[];line.GeneratedDecorations=[];line.DecorationIds=[];}
  var completedMembers=previous.Sites.Where(site=>site.ParcelGeneration is not null).SelectMany(site=>site.BuildingIds).ToHashSet();var completedFences=previous.Sites.SelectMany(site=>site.ParcelGeneration?.Objects.Keys??Enumerable.Empty<string>()).Where(k=>k.StartsWith("fence:",StringComparison.Ordinal)).Select(k=>k[6..]).ToHashSet();
  p.Buildings=p.Buildings.Where(b=>completedMembers.Contains(b.Id)||b.SourceKind=="parcel-generator"||b.SourceId is null||b.Modified||p.Generation?.LockedBuildingIds.Contains(b.Id)==true||p.Sites.Any(s=>s.Locked&&s.BuildingIds.Contains(b.Id))).ToList();
  p.Decorations=p.Decorations.Where(d=>!GeographicImporter.IsBuiltInDressing(d)).ToList();p.Fences=p.Fences.Where(f=>f.SourceId is null||completedFences.Contains(f.Id)).ToList();p.SourceFeatures=p.SourceFeatures.Where(f=>f.Modified||f.Origin!="source").ToList();foreach(var feature in p.SourceFeatures)if(feature.BuildingId is {} id&&!p.Buildings.Any(b=>b.Id==id))feature.BuildingId=null;
  p.Sites=p.Sites.Where(s=>s.Locked||s.Origin!="source"||s.ParcelGeneration is not null).ToList();
  for(var i=0;i<p.Terrain.Length;i++){if((i&4095)==0)token.ThrowIfCancellationRequested();if(TerrainEditMask.IsEdited(mask,i))p.Terrain[i]=terrain[i];}
  void Keep(int x,int y){if(x>=0&&y>=0&&x<p.Width&&y<p.Height)p.Terrain[y*p.Width+x]=terrain[y*p.Width+x];}
  foreach(var i in p.SurfaceTiles.Keys)p.Terrain[i]=terrain[i];foreach(var model in p.StaticModels)foreach(var cell in StaticModelPlacement.FootprintCells(model))Keep(model.X+cell.Dx,model.Y+cell.Dy);foreach(var d in p.Decorations)foreach(var part in d.Parts)Keep(d.X+part.Dx,d.Y+part.Dy);foreach(var spawn in p.Spawns)Keep(spawn.X,spawn.Y);
  foreach(var building in p.Buildings)foreach(var cell in BuildingDesigner.Occupied(building,false))Keep(building.X+cell%(building.Width+1),building.Y+cell/(building.Width+1));
  foreach(var state in previous.Sites.Select(site=>site.ParcelGeneration).OfType<ParcelGenerationState>())foreach(var i in state.Ground.Keys)p.Terrain[i]=terrain[i];
  if(lines.Count>0)p=LinearFeatureEditor.Rebuild(p,lines);SiteModel.DetachMissingMembers(p);p.ImportSummary=new(){PlacedBuildings=p.Buildings.Count,Notes=["The refreshed section has no source features. Authored layers were preserved; previous source objects and unmarked terrain were refreshed."]};ProjectValidator.Validate(p);return p;
 }
 public void Dispose(){lock(admission){disposed=true;foreach(var job in jobs.Values)job.Cancel.Cancel();}}
}
